mapper.select:
select * from yh_user_oxygen where is_del=2 AND E_User_Id=#{usercode}

  AND Entry_Time >=  #{strTime} AND Entry_Time <= #{endTime}


  AND Entry_Time LIKE CONCAT('',#{strTime},'%')


  AND YEAR(Entry_Time) =#{strTime}

  SELECT COUNT(*) FROM (
	SELECT * FROM `yh_user_oxygen` WHERE  E_User_Id=#{usercode} AND Is_Del=2

      AND  Entry_Time >=  #{strTime} AND Entry_Time <= #{endTime}


      AND  Entry_Time LIKE CONCAT('',#{strTime},'%')


      AND YEAR(Entry_Time) =#{strTime}


    LIMIT #{page}
	) AS a  WHERE a.oxygen>=95

  SELECT COUNT(*) FROM (
	SELECT * FROM `yh_user_oxygen` WHERE  E_User_Id=#{usercode} AND Is_Del=2

       AND  Entry_Time >=  #{strTime} AND Entry_Time <= #{endTime}


       AND  Entry_Time LIKE CONCAT('',#{strTime},'%')


       AND YEAR(Entry_Time) =#{strTime}


     LIMIT #{page}
	) AS a  WHERE a.oxygen<95
